(async () => {
  const btn = document.querySelector('.header__cta');
  if (!btn) return {error: 'no header cta'};
  const trig = btn.hasAttribute('data-quote-open');
  btn.click();
  await new Promise(r => setTimeout(r, 500));
  const m = document.getElementById('gquote');
  const wa = document.querySelector('.wa-float');
  const out = {trigger: trig, opened: m ? !m.hidden : null,
               waFloat: wa ? wa.getAttribute('href') : null,
               fields: m ? [...m.querySelectorAll('input,select,textarea')].map(f=>f.name).filter(Boolean) : []};
  if (m) m.querySelector('[data-gq-close]').click();
  return out;
})()
